import{_ as t,o,c as n,a5 as c}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"02 — Xác thực, Phân quyền & Hồ sơ Người dùng / Khách hàng (Authentication, Authorization & Profiles)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/02-authentication-profile.md","filePath":"ba/02-authentication-profile.md"}'),d={name:"ba/02-authentication-profile.md"};function i(l,e,a,r,h,g){return o(),n("div",null,[...e[0]||(e[0]=[c('<h1 id="_02-—-xac-thuc-phan-quyen-ho-so-nguoi-dung-khach-hang-authentication-authorization-profiles" tabindex="-1">02 — Xác thực, Phân quyền &amp; Hồ sơ Người dùng / Khách hàng (Authentication, Authorization &amp; Profiles) <a class="header-anchor" href="#_02-—-xac-thuc-phan-quyen-ho-so-nguoi-dung-khach-hang-authentication-authorization-profiles" aria-label="Permalink to &quot;02 — Xác thực, Phân quyền &amp; Hồ sơ Người dùng / Khách hàng (Authentication, Authorization &amp; Profiles)&quot;">​</a></h1><p>&gt; [&lt;&lt; 01 - Organization Structure](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/01-organization-structure.md) | [Overview](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/00-overview.md) | [Tiếp: 03 - Agency &amp; Workspace &gt;&gt;](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/03-agency-workspace-management.md) &gt; &gt; <strong>Phạm vi FR chuẩn</strong>: &gt; - <strong>Mục <code>3.2 Authentication &amp; Authorization</code></strong>: <strong>9 FR (<code>3.2.1</code> – <code>3.2.9</code>)</strong> | <code>UC-001</code> – <code>UC-009</code> &gt; - <strong>Mục <code>3.3 User &amp; Client Profile</code></strong>: <strong>4 FR (<code>3.3.1</code> – <code>3.3.4</code>)</strong> | <code>UC-010</code> – <code>UC-013</code></p><hr><h2 id="_1-bang-tong-hop-yeu-cau-chuc-nang-chuan-3-2-3-3-—-13-frs" tabindex="-1">1. Bảng Tổng hợp Yêu cầu Chức năng Chuẩn (<code>3.2</code> &amp; <code>3.3</code> — 13 FRs) <a class="header-anchor" href="#_1-bang-tong-hop-yeu-cau-chuc-nang-chuan-3-2-3-3-—-13-frs" aria-label="Permalink to &quot;1. Bảng Tổng hợp Yêu cầu Chức năng Chuẩn (`3.2` &amp; `3.3` — 13 FRs)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã FR</th><th style="text-align:center;">Mã UC</th><th style="text-align:left;">Tên Chức năng Chuẩn (Atomic CRUD FR)</th><th style="text-align:left;">Actors / Roles Chuẩn</th><th style="text-align:left;">Mô tả Nghiệp vụ Cốt lõi</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><code>3.2.1</code></strong></td><td style="text-align:center;"><code>UC-001</code></td><td style="text-align:left;"><strong>Register Account</strong></td><td style="text-align:left;"><code>Guest</code></td><td style="text-align:left;">Đăng ký tài khoản mới bằng Email, Mật khẩu và Họ tên; gửi mã OTP xác thực qua email.</td></tr><tr><td style="text-align:center;"><strong><code>3.2.2</code></strong></td><td style="text-align:center;"><code>UC-002</code></td><td style="text-align:left;"><strong>Login</strong></td><td style="text-align:left;"><code>Guest</code></td><td style="text-align:left;">Đăng nhập vào hệ thống bằng Email &amp; Mật khẩu; cấp cặp JWT (<code>accessToken</code> + <code>refreshToken</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.2.3</code></strong></td><td style="text-align:center;"><code>UC-003</code></td><td style="text-align:left;"><strong>Social Login (Google)</strong></td><td style="text-align:left;"><code>Guest</code></td><td style="text-align:left;">Đăng nhập hoặc đăng ký nhanh một chạm thông qua tài khoản Google OAuth 2.0.</td></tr><tr><td style="text-align:center;"><strong><code>3.2.4</code></strong></td><td style="text-align:center;"><code>UC-004</code></td><td style="text-align:left;"><strong>Verify Email</strong></td><td style="text-align:left;"><code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Xác thực địa chỉ email bằng mã OTP 6 chữ số để kích hoạt tài khoản (<code>status = ACTIVE</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.2.5</code></strong></td><td style="text-align:center;"><code>UC-005</code></td><td style="text-align:left;"><strong>Forgot Password</strong></td><td style="text-align:left;"><code>Guest</code></td><td style="text-align:left;">Yêu cầu đặt lại mật khẩu khi quên; hệ thống gửi mã OTP đặt lại mật khẩu về email đã đăng ký.</td></tr><tr><td style="text-align:center;"><strong><code>3.2.6</code></strong></td><td style="text-align:center;"><code>UC-006</code></td><td style="text-align:left;"><strong>Change Password</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:left;">Đổi mật khẩu khi đã đăng nhập (yêu cầu nhập đúng mật khẩu hiện tại) hoặc đặt lại mật khẩu mới sau bước xác thực OTP.</td></tr><tr><td style="text-align:center;"><strong><code>3.2.7</code></strong></td><td style="text-align:center;"><code>UC-007</code></td><td style="text-align:left;"><strong>Setup Two-Factor Authentication</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:left;">Bật/tắt và cấu hình xác thực 2 yếu tố (2FA TOTP qua ứng dụng Google Authenticator / Authy kèm mã khôi phục dự phòng).</td></tr><tr><td style="text-align:center;"><strong><code>3.2.8</code></strong></td><td style="text-align:center;"><code>UC-008</code></td><td style="text-align:left;"><strong>Logout</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:left;">Đăng xuất khỏi phiên làm việc hiện tại; thu hồi <code>refreshToken</code> trên Redis/DB và xóa trạng thái phiên trên trình duyệt.</td></tr><tr><td style="text-align:center;"><strong><code>3.2.9</code></strong></td><td style="text-align:center;"><code>UC-009</code></td><td style="text-align:left;"><strong>Delete Account</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Yêu cầu xóa/vô hiệu hóa tài khoản cá nhân (cần xác nhận mật khẩu và kiểm tra không còn giữ quyền <code>Owner</code> duy nhất của Agency đang hoạt động).</td></tr><tr><td style="text-align:center;"><strong><code>3.3.1</code></strong></td><td style="text-align:center;"><code>UC-010</code></td><td style="text-align:left;"><strong>View User Profile</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:left;">Xem thông tin hồ sơ cá nhân của bản thân (Họ tên, Email, Ảnh đại diện, Số điện thoại, Chức danh, Múi giờ, Ngôn ngữ làm việc <code>vi</code>/<code>en</code>, trạng thái 2FA).</td></tr><tr><td style="text-align:center;"><strong><code>3.3.2</code></strong></td><td style="text-align:center;"><code>UC-011</code></td><td style="text-align:left;"><strong>Update User Profile</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:left;">Cập nhật thông tin hồ sơ cá nhân, tải lên ảnh đại diện mới và đổi ngôn ngữ giao diện/email (<code>workingLanguage</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.3.3</code></strong></td><td style="text-align:center;"><code>UC-012</code></td><td style="text-align:left;"><strong>View Client Profile</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Xem hồ sơ thương hiệu của Khách hàng (<code>ClientProfile</code>) gắn với Workspace (Tên thương hiệu, Logo, Ngành hàng, Website, Bộ nhận diện, Thông tin liên hệ).</td></tr><tr><td style="text-align:center;"><strong><code>3.3.4</code></strong></td><td style="text-align:center;"><code>UC-013</code></td><td style="text-align:left;"><strong>Update Client Profile</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:left;">Cập nhật thông tin hồ sơ thương hiệu Khách hàng (<code>ClientProfile</code>), tải lên logo thương hiệu (dùng cho xuất file PDF/DOCX và tên hiển thị người gửi Newsletter).</td></tr></tbody></table><hr><h2 id="_2-đac-ta-chi-tiet-nhom-3-2-authentication-authorization" tabindex="-1">2. Đặc tả Chi tiết Nhóm <code>3.2 Authentication &amp; Authorization</code> <a class="header-anchor" href="#_2-đac-ta-chi-tiet-nhom-3-2-authentication-authorization" aria-label="Permalink to &quot;2. Đặc tả Chi tiết Nhóm `3.2 Authentication &amp; Authorization`&quot;">​</a></h2><h3 id="_2-1-3-2-1-register-account-3-2-4-verify-email" tabindex="-1">2.1. <code>3.2.1 Register Account</code> &amp; <code>3.2.4 Verify Email</code> <a class="header-anchor" href="#_2-1-3-2-1-register-account-3-2-4-verify-email" aria-label="Permalink to &quot;2.1. `3.2.1 Register Account` &amp; `3.2.4 Verify Email`&quot;">​</a></h3><ul><li><strong>Actor</strong>: <code>Guest</code> (đăng ký) → xác thực OTP để kích hoạt tài khoản.</li><li><strong>Quy tắc kiểm tra đầu vào (Validation Rules)</strong>: <ul><li><code>email</code>: Định dạng email hợp lệ, chuẩn hóa chữ thường (<code>lowercase</code>), duy nhất trong bảng <code>users</code>. Nếu đã tồn tại tài khoản <code>ACTIVE</code> → báo lỗi email đã được sử dụng.</li><li><code>password</code>: Tối thiểu 8 ký tự, bao gồm chữ hoa, chữ thường, chữ số và ký tự đặc biệt; băm bằng <code>BCryptPasswordEncoder</code> trước khi lưu.</li><li><code>displayName</code> / <code>fullName</code>: Bắt buộc, từ 2 đến 100 ký tự.</li></ul></li><li><strong>Luồng xử lý chuẩn</strong>: <ol><li>Tạo bản ghi <code>User</code> ở trạng thái chờ xác thực email (<code>emailVerified = false</code>).</li><li>Sinh mã OTP 6 chữ số có thời hạn hiệu lực (TTL 5–10 phút lưu trên Redis) và gửi email qua <code>MailService</code> theo ngôn ngữ người dùng chọn (<code>vi</code> hoặc <code>en</code>).</li><li>Tại màn hình <code>Verify Email (3.2.4)</code>, người dùng nhập mã OTP: <ul><li>Nếu khớp và còn hạn: cập nhật <code>emailVerified = true</code>, <code>status = ACTIVE</code>, cấp JWT để đăng nhập ngay và hiển thị màn hình chọn hướng bắt đầu (<strong>Bắt đầu với Không gian Cá nhân — Personal Studio</strong> hoặc <strong>Thiết lập Công ty — Agency B2B</strong>).</li><li>Hỗ trợ gửi lại OTP (<code>Resend OTP</code>) có giới hạn tần suất (cooldown 60 giây) để chống spam.</li></ul></li></ol></li></ul><h3 id="_2-2-3-2-2-login-3-2-3-social-login-google" tabindex="-1">2.2. <code>3.2.2 Login</code> &amp; <code>3.2.3 Social Login (Google)</code> <a class="header-anchor" href="#_2-2-3-2-2-login-3-2-3-social-login-google" aria-label="Permalink to &quot;2.2. `3.2.2 Login` &amp; `3.2.3 Social Login (Google)`&quot;">​</a></h3><ul><li><strong>Actor</strong>: <code>Guest</code>.</li><li><strong>Luồng <code>3.2.2 Login</code></strong>: <ol><li>Kiểm tra tồn tại <code>email</code> và đối chiếu <code>password</code> qua BCrypt.</li><li>Kiểm tra trạng thái tài khoản: <ul><li>Nếu <code>status == BANNED</code> / <code>LOCKED</code> (do <code>Admin</code> khóa tại FR <code>3.10.3</code> / <code>3.10.5</code>) → từ chối đăng nhập kèm thông báo tài khoản bị khóa.</li><li>Nếu <code>emailVerified == false</code> → chuyển hướng sang bước <code>3.2.4 Verify Email</code>.</li></ul></li><li>Nếu tài khoản đã bật 2FA (<code>twoFactorEnabled == true</code>) → trả về cờ <code>requiresTwoFactor = true</code> và <code>tempAuthToken</code> để người dùng nhập mã TOTP 6 số từ ứng dụng xác thực.</li><li>Khi hợp lệ hoàn toàn → cấp <code>accessToken</code> + <code>refreshToken</code> và điều hướng theo vai trò: <ul><li>Nếu là <code>Admin</code> (<code>systemRole == ADMIN</code>) → điều hướng vào <code>/admin/dashboard</code>.</li><li>Nếu là <code>Client</code> → điều hướng vào <code>/workspaces/:id/portal</code> (Cổng Khách hàng).</li><li>Nếu là <code>Owner</code>, <code>Manager</code>, <code>Creator</code> → điều hướng vào không gian làm việc gần nhất hoặc trang Hub <code>/agency</code> (nơi có sẵn nút 1 chạm vào <strong>Personal Studio</strong>).</li></ul></li></ol></li><li><strong>Luồng <code>3.2.3 Social Login (Google)</code></strong>: <ul><li>Xác thực <code>idToken</code> / OAuth code với Google.</li><li>Nếu email chưa tồn tại trong hệ thống: tự động tạo tài khoản <code>User</code> mới với <code>emailVerified = true</code>, <code>authProvider = GOOGLE</code>, lấy tên và ảnh đại diện từ Google.</li><li>Nếu email đã tồn tại và đang <code>ACTIVE</code>: liên kết tài khoản Google và cấp phiên đăng nhập ngay.</li></ul></li></ul><h3 id="_2-3-3-2-5-forgot-password-3-2-6-change-password" tabindex="-1">2.3. <code>3.2.5 Forgot Password</code> &amp; <code>3.2.6 Change Password</code> <a class="header-anchor" href="#_2-3-3-2-5-forgot-password-3-2-6-change-password" aria-label="Permalink to &quot;2.3. `3.2.5 Forgot Password` &amp; `3.2.6 Change Password`&quot;">​</a></h3><ul><li><strong><code>3.2.5 Forgot Password</code> (<code>Guest</code>)</strong>: <ul><li>Người dùng nhập <code>email</code> đã đăng ký → hệ thống gửi mã OTP khôi phục mật khẩu qua email → người dùng nhập OTP kèm <code>newPassword</code> + <code>confirmPassword</code> → cập nhật mật khẩu mới và thu hồi toàn bộ các phiên đăng nhập cũ của tài khoản đó.</li></ul></li><li><strong><code>3.2.6 Change Password</code> (<code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>)</strong>: <ul><li>Người dùng đang đăng nhập vào trang Cài đặt bảo mật (<code>/profile</code>), nhập <code>currentPassword</code>, <code>newPassword</code>, <code>confirmPassword</code>.</li><li>Mật khẩu mới không được trùng với mật khẩu hiện tại.</li></ul></li></ul><h3 id="_2-4-3-2-7-setup-two-factor-authentication-2fa" tabindex="-1">2.4. <code>3.2.7 Setup Two-Factor Authentication (2FA)</code> <a class="header-anchor" href="#_2-4-3-2-7-setup-two-factor-authentication-2fa" aria-label="Permalink to &quot;2.4. `3.2.7 Setup Two-Factor Authentication (2FA)`&quot;">​</a></h3><ul><li><strong>Actors</strong>: <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>.</li><li><strong>Luồng bật 2FA</strong>: <ol><li>Hệ thống sinh khóa bí mật TOTP (<code>secretKey</code>) và mã QR chuẩn <code>otpauth://totp/BrandHub:&lt;email&gt;</code>.</li><li>Người dùng quét mã QR bằng Google Authenticator / Authy và nhập mã xác nhận 6 số đầu tiên.</li><li>Hệ thống kích hoạt <code>twoFactorEnabled = true</code> và cung cấp danh sách mã khôi phục dự phòng (<code>recoveryCodes</code>).</li></ol></li><li><strong>Luồng tắt 2FA</strong>: Yêu cầu xác nhận mật khẩu hiện tại hoặc mã OTP hợp lệ.</li></ul><h3 id="_2-5-3-2-8-logout-3-2-9-delete-account" tabindex="-1">2.5. <code>3.2.8 Logout</code> &amp; <code>3.2.9 Delete Account</code> <a class="header-anchor" href="#_2-5-3-2-8-logout-3-2-9-delete-account" aria-label="Permalink to &quot;2.5. `3.2.8 Logout` &amp; `3.2.9 Delete Account`&quot;">​</a></h3><ul><li><strong><code>3.2.8 Logout</code></strong>: Thu hồi <code>refreshToken</code> hiện tại ở phía Server và xóa token lưu ở phía Client, đưa người dùng về <code>/login</code>.</li><li><strong><code>3.2.9 Delete Account</code></strong>: <ul><li>Cho phép <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code> yêu cầu xóa/đóng tài khoản của mình.</li><li><strong>Ràng buộc toàn vẹn</strong>: Nếu người dùng đang là <code>Owner</code> của một <code>Agency</code> B2B có các thành viên khác đang hoạt động, hệ thống yêu cầu chuyển quyền hoặc đóng Agency trước khi xóa tài khoản. Thực hiện soft-delete (<code>deletedAt = now()</code>, <code>status = DELETED</code>) để giữ toàn vẹn lịch sử kiểm toán (<code>audit log</code>) và hóa đơn tài chính.</li></ul></li></ul><hr><h2 id="_3-đac-ta-chi-tiet-nhom-3-3-user-client-profile" tabindex="-1">3. Đặc tả Chi tiết Nhóm <code>3.3 User &amp; Client Profile</code> <a class="header-anchor" href="#_3-đac-ta-chi-tiet-nhom-3-3-user-client-profile" aria-label="Permalink to &quot;3. Đặc tả Chi tiết Nhóm `3.3 User &amp; Client Profile`&quot;">​</a></h2><h3 id="_3-1-ho-so-nguoi-dung-ca-nhan-3-3-1-view-user-profile-3-3-2-update-user-profile" tabindex="-1">3.1. Hồ sơ Người dùng Cá nhân (<code>3.3.1 View User Profile</code> &amp; <code>3.3.2 Update User Profile</code>) <a class="header-anchor" href="#_3-1-ho-so-nguoi-dung-ca-nhan-3-3-1-view-user-profile-3-3-2-update-user-profile" aria-label="Permalink to &quot;3.1. Hồ sơ Người dùng Cá nhân (`3.3.1 View User Profile` &amp; `3.3.2 Update User Profile`)&quot;">​</a></h3><ul><li><strong>Actors</strong>: <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>.</li><li><strong>Các trường dữ liệu quản lý</strong>: <ul><li><code>displayName</code> / <code>fullName</code> (Họ và tên hiển thị)</li><li><code>avatarUrl</code> (Ảnh đại diện tải lên kho lưu trữ đối tượng S3/MinIO)</li><li><code>phone</code> (Số điện thoại liên hệ)</li><li><code>jobTitle</code> / <code>bio</code> (Chức danh / Giới thiệu ngắn)</li><li><code>timezone</code> (Múi giờ mặc định, VD: <code>Asia/Ho_Chi_Minh</code>)</li><li><code>workingLanguage</code> (<code>vi</code> hoặc <code>en</code> — quyết định ngôn ngữ giao diện và ngôn ngữ của các email hệ thống gửi tới người dùng đó).</li></ul></li><li><strong>Quy tắc bảo mật</strong>: Trường <code>email</code> là định danh đăng nhập nên hiển thị chỉ-đọc (read-only) trên form cập nhật hồ sơ thường.</li></ul><h3 id="_3-2-ho-so-thuong-hieu-khach-hang-3-3-3-view-client-profile-3-3-4-update-client-profile" tabindex="-1">3.2. Hồ sơ Thương hiệu Khách hàng (<code>3.3.3 View Client Profile</code> &amp; <code>3.3.4 Update Client Profile</code>) <a class="header-anchor" href="#_3-2-ho-so-thuong-hieu-khach-hang-3-3-3-view-client-profile-3-3-4-update-client-profile" aria-label="Permalink to &quot;3.2. Hồ sơ Thương hiệu Khách hàng (`3.3.3 View Client Profile` &amp; `3.3.4 Update Client Profile`)&quot;">​</a></h3><ul><li><strong>Actors</strong>: <ul><li>Xem (<code>3.3.3</code>): <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code> trong Workspace.</li><li>Cập nhật (<code>3.3.4</code>): <code>Owner</code>, <code>Manager</code>, <code>Client</code> trong Workspace.</li></ul></li><li><strong>Các trường dữ liệu quản lý (<code>client_profiles</code>)</strong>: <ul><li><code>displayName</code> / <code>brandName</code> (Tên thương hiệu hiển thị — đồng thời được dùng làm <code>From Name</code> khi gửi bản tin <code>EMAIL_NEWSLETTER</code> của thương hiệu đó).</li><li><code>logoUrl</code> (Logo thương hiệu lưu trên bucket nội bộ <code>image/client-logos/&lt;profileId&gt;/...</code> — được in lên đầu trang khi xuất file PDF/DOCX của công việc hoặc gói dịch vụ).</li><li><code>industry</code> (Ngành hàng / Lĩnh vực hoạt động).</li><li><code>website</code>, <code>contactEmail</code>, <code>contactPhone</code>, <code>address</code>.</li><li><code>brandGuidelines</code> / <code>toneOfVoice</code> (Mô tả giọng văn và định hướng thương hiệu, phục vụ ngữ cảnh cho AI sinh nội dung).</li></ul></li><li><strong>Hành vi trong Chế độ <code>PERSONAL</code> (<code>workspaceMode = &quot;PERSONAL&quot;</code>)</strong>: <ul><li>Trong Workspace <code>PERSONAL</code>, menu <code>Hồ sơ Khách hàng (/client-profile)</code> được ẩn khỏi Sidebar để giao diện gọn nhẹ; các thông tin tên dự án/thương hiệu cá nhân (<code>brandName</code>, <code>industry</code>, <code>timezoneConfig</code>) được chỉnh sửa trực tiếp ngay trong trang <strong>Cài đặt Không gian (<code>/workspaces/:id/settings</code>)</strong>. Nếu người dùng nâng cấp Workspace sang chế độ <code>&quot;AGENCY&quot;</code>, trang <code>Hồ sơ Khách hàng</code> sẽ tự động hiển thị trở lại.</li></ul></li></ul>',23)])])}const m=t(d,[["render",i]]);export{u as __pageData,m as default};
